const visual = {
  prepare: function (input) { return []; },
  render: function (input, metrics) {
    var vw = input.viewport.widthDu;
    var vh = input.viewport.heightDu;
    var n = 5;
    var margin = 24;
    var size = Math.min(vw - 2 * margin, vh - 2 * margin);
    if (!(size > 0)) { size = Math.min(vw, vh) * 0.8; }
    var x0 = (vw - size) / 2;
    var y0 = (vh - size) / 2;
    var cell = size / n;
    var cmds = [];
    for (var i = 0; i <= n; i++) {
      var x = x0 + i * cell;
      cmds.push('M', x, y0, 'L', x, y0 + size);
      var y = y0 + i * cell;
      cmds.push('M', x0, y, 'L', x0 + size, y);
    }
    return {
      schemaVersion: 1,
      sceneId: 'grid-5x5',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: vw, height: vh },
      paths: [{ id: 'grid', commands: cmds }],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'grid', stroke: '#26354a', strokeWidth: 1.5, fill: 'none' }
        ]
      }
    };
  }
};
